def check_condition(h, a1, a1b):
    # For every prime power p^v that divides h, 
    # we need p^v to divide a1 or p^v to divide a1b.
    # Wait, the condition is gcd(h, k) divides a1 or a1b.
    # This is true if for every prime p, 
    # the largest power of p dividing h, say p^v, divides a1 or a1b.
    d = h
    p = 2
    while p * p <= d:
        if d % p == 0:
            pv = 1
            while d % p == 0:
                pv *= p
                d //= p
            if a1 % pv != 0 and a1b % pv != 0:
                return False
        p += 1
    if d > 1:
        if a1 % d != 0 and a1b % d != 0:
            return False
    return True

