def check_condition(H, a1, target):
    if H == 0: return False # a_n would be constant
    H_abs = abs(H)
    d = H_abs
    p = 2
    while p * p <= d:
        if d % p == 0:
            pv = 1
            while d % p == 0:
                pv *= p
                d //= p
            if a1 % pv != 0 and target % pv != 0:
                return False
        p += 1
    if d > 1:
        if a1 % d != 0 and target % d != 0:
            return False
    return True

