# Case 1: H = b+d, max 2b-H
max_val1 = -1e9
for b in range(2025, 10001):
    # d = H-b, so 2025 <= H-b <= 10000 => b+2025 <= H <= b+10000
    # We want to maximize 2b-H, so minimize H.
    # For a fixed b, we want the smallest H >= b+2025.
    for h in range(b + 2025, b + 10001):
        if check_condition(h, a1, a1 + b):
            val = 2 * b - h
            if val > max_val1:
                max_val1 = val
            break # Found smallest h for this b
print(f"Case 1: {max_val1}")

# Case 2: H = d-b, max -H
max_val2 = -1e9
for b in range(2025, 10001):
    # d = b+H, so 2025 <= b+H <= 10000 => 2025-b <= H <= 10000-b
    # We want to maximize -H, so minimize H.
    for h in range(2025 - b, 10000 - b + 1):
        if check_condition(h, a1, b - a1):
            val = -h
            if val > max_val2:
                max_val2 = val
            break # Found smallest h for this b
print(f"Case 2: {max_val2}")

